//! Chain vectors for `blocks/chain/chain.h`, generated by
//! `scripts/cpp_vectors/chain_vectors.cpp`.

use std::collections::HashMap;

use fp_core::chain::chain::{
    draw_e_straight, Chain, ChainKind, FirstQuery,
};
use fp_core::chain::rounds::{record_seeds, SampleSeed};
use fp_core::field::ext::{F, E};
use fp_core::hash::calls::HashCalls;
use fp_core::hash::modes::Digest;

const VECTORS: &str = include_str!("../../fixtures/chain_vectors.txt");

fn fields(line: &str) -> HashMap<&str, &str> {
    line.split_whitespace()
        .filter_map(|t| t.split_once('='))
        .map(|(k, v)| (k, v))
        .collect()
}

fn digest(s: &str) -> Digest {
    assert_eq!(s.len(), 64, "digest {}", s);
    let mut d = Digest::zero();
    for i in 0..8 {
        d.w[i] = u32::from_str_radix(&s[8 * i..8 * i + 8], 16).unwrap();
    }
    d
}

fn f(s: &str) -> F {
    F(u64::from_str_radix(s, 16).unwrap())
}

fn e(s: &str) -> E {
    let p: Vec<&str> = s.split(',').collect();
    assert_eq!(p.len(), 3, "E {}", s);
    E([f(p[0]), f(p[1]), f(p[2])])
}

fn bytes(s: &str) -> Vec<u8> {
    if s == "-" {
        return Vec::new();
    }
    (0..s.len() / 2)
        .map(|i| u8::from_str_radix(&s[2 * i..2 * i + 2], 16).unwrap())
        .collect()
}

fn words(s: &str) -> Vec<u64> {
    if s == "-" {
        return Vec::new();
    }
    s.split(',').map(|x| u64::from_str_radix(x, 16).unwrap()).collect()
}

fn kind(n: u32) -> ChainKind {
    match n {
        1 => ChainKind::Algebraic,
        2 => ChainKind::Epsilon,
        3 => ChainKind::Seed,
        4 => ChainKind::Positions,
        5 => ChainKind::Bits,
        6 => ChainKind::Seal,
        7 => ChainKind::Empty,
        _ => panic!("kind {}", n),
    }
}

fn trits(chain: &mut Chain, n: usize, calls: &mut HashCalls) -> Vec<i8> {
    let mut t = vec![0i8; n];
    let mut i = 0usize;
    while i < n {
        let mut w = chain.next_word(calls);
        let mut j = 0usize;
        while j < 32 && i + j < n {
            let b0 = (w & 1) as i32;
            let b1 = ((w & (w << 1) & 2) >> 1) as i32;
            t[i + j] = (b0 - 2 * b1) as i8;
            w >>= 2;
            j += 1;
        }
        i += 32;
    }
    t
}

#[test]
fn chain_vectors_match_the_cpp_reference() {
    let mut chain: Option<Chain> = None;
    let mut calls = HashCalls::new();
    let mut seeds: Vec<SampleSeed> = Vec::new();
    let mut lines = 0usize;
    let mut rounds = 0usize;

    for line in VECTORS.lines() {
        lines += 1;
        let first = line.split_whitespace().next().unwrap();
        let tag = first.split('=').next().unwrap();
        let kv = fields(line);
        match tag {
            "CASE" => {}
            "CHAIN" => {
                let q = FirstQuery {
                    label: u64::from_str_radix(kv["label"], 16).unwrap(),
                    parameters: digest(kv["params"]),
                    statement: bytes(kv["statement"]),
                    record: bytes(kv["record"]),
                    salted: kv["salted"] == "1",
                    salt_in_proof: true,
                    salt: digest(kv["salt"]),
                };
                calls.begin();
                let c = Chain::new(&q, &mut calls);
                assert_eq!(c.value(), &digest(kv["rho"]), "first query at line {}", lines);
                assert_eq!(c.rounds(), 0);
                assert_eq!(calls.blk, kv["calls"].parse::<u64>().unwrap(), "calls at line {}", lines);
                chain = Some(c);
            }
            "STEP" => {
                assert_eq!(kv["ok"], "1", "step at line {}", lines);
            }
            "ROUND" => {
                let c = chain.as_mut().unwrap();
                let k = kind(kv["kind"].parse().unwrap());
                let work: u32 = kv["work"].parse().unwrap();
                let nonce = u64::from_str_radix(kv["nonce"], 16).unwrap();
                let ws = words(kv["words"]);
                let mut m = c.message(&mut calls);
                for w in &ws {
                    m.push_u64(*w);
                }
                let p = Chain::prefix(&mut m, k, work);
                assert!(c.step(&p, nonce, work, &mut calls), "work at line {}", lines);
                assert_eq!(c.value(), &digest(kv["rho"]), "rho at line {}", lines);
                assert_eq!(c.rounds(), kv["rounds"].parse::<u64>().unwrap());
                assert_eq!(calls.blk, kv["calls"].parse::<u64>().unwrap(), "calls at line {}", lines);
                rounds += 1;
            }
            "DRAW_E" => {
                let got = chain.as_mut().unwrap().draw_e(&mut calls);
                assert_eq!(got, e(kv["x"]), "draw at line {}", lines);
                assert_eq!(calls.blk, kv["calls"].parse::<u64>().unwrap(), "calls at line {}", lines);
            }
            "DRAW_F" => {
                let got = chain.as_mut().unwrap().draw_f(&mut calls);
                assert_eq!(got, f(kv["x"]), "draw at line {}", lines);
                assert_eq!(calls.blk, kv["calls"].parse::<u64>().unwrap(), "calls at line {}", lines);
            }
            "POS" => {
                let got = chain
                    .as_mut()
                    .unwrap()
                    .draw_position(kv["log_n"].parse().unwrap(), &mut calls);
                assert_eq!(got, kv["p"].parse::<u64>().unwrap(), "position at line {}", lines);
                assert_eq!(calls.blk, kv["calls"].parse::<u64>().unwrap(), "calls at line {}", lines);
            }
            "BITS" => {
                let n: usize = kv["n"].parse().unwrap();
                let want: Vec<i8> = kv["v"].split(',').map(|x| x.parse().unwrap()).collect();
                let got = trits(chain.as_mut().unwrap(), n, &mut calls);
                assert_eq!(got, want, "trits at line {}", lines);
                assert_eq!(calls.blk, kv["calls"].parse::<u64>().unwrap(), "calls at line {}", lines);
            }
            "SEAL" => {
                let mut d = Digest::zero();
                for i in 0..4 {
                    let w = chain.as_mut().unwrap().next_word(&mut calls);
                    d.w[2 * i] = w as u32;
                    d.w[2 * i + 1] = (w >> 32) as u32;
                }
                assert_eq!(d, digest(kv["SEAL"]), "seal at line {}", lines);
                assert_eq!(calls.blk, kv["calls"].parse::<u64>().unwrap(), "calls at line {}", lines);
            }
            "FINAL" => {
                let c = chain.as_ref().unwrap();
                assert_eq!(c.value(), &digest(kv["rho"]), "final at line {}", lines);
                assert_eq!(c.rounds(), kv["rounds"].parse::<u64>().unwrap());
                assert_eq!(calls.blk, kv["calls"].parse::<u64>().unwrap(), "calls at line {}", lines);
            }
            "STRAIGHT" => {
                let mut out = E::default();
                let got = draw_e_straight(
                    u64::from_str_radix(kv["w0"], 16).unwrap(),
                    u64::from_str_radix(kv["w1"], 16).unwrap(),
                    u64::from_str_radix(kv["w2"], 16).unwrap(),
                    kv["nz"] == "1",
                    &mut out,
                );
                assert_eq!(got, kv["ok"] == "1", "straight at line {}", lines);
                assert_eq!(out, e(kv["x"]), "straight value at line {}", lines);
            }
            "SEEDS" => {
                let commitment = bytes(kv["commitment"]);
                calls.begin();
                seeds = record_seeds(&commitment, 3, 2, &mut calls);
                assert_eq!(seeds.len(), kv["n"].parse::<usize>().unwrap());
                assert_eq!(calls.blk, kv["calls"].parse::<u64>().unwrap(), "seed calls at line {}", lines);
            }
            "SEED" => {
                let i: usize = kv["i"].parse().unwrap();
                assert_eq!(seeds[i].beta, e(kv["beta"]), "seed beta at line {}", lines);
                let z: Vec<E> = kv["z"].split(';').map(e).collect();
                assert_eq!(seeds[i].z, z, "seed z at line {}", lines);
            }
            other => panic!("line {}: unknown tag {}", lines, other),
        }
    }
    assert!(lines > 0 && rounds > 0);
}
